-- Crash alerts + webhooks (Feature 1).
--
-- Generated by hand to match the Drizzle output style; after adding the
-- matching tables to database/src/schema.ts, regenerate the snapshot
-- with `pnpm --filter database kit:generate` and confirm this file is
-- unchanged apart from formatting. Do NOT edit snapshot.json by hand.

CREATE TYPE "server_webhook_kind" AS ENUM('DISCORD', 'GENERIC');
CREATE TYPE "server_webhook_event" AS ENUM('SERVER_CRASHED', 'SERVER_OFFLINE', 'SERVER_RECOVERED');
CREATE TYPE "server_alert_kind" AS ENUM('CRASHED', 'OFFLINE', 'RECOVERED');

CREATE TABLE "server_webhooks" (
	"uuid" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"server_uuid" uuid,
	"name" varchar(255) NOT NULL,
	"kind" "server_webhook_kind" NOT NULL,
	"url" varchar(2048) NOT NULL,
	"events" "server_webhook_event"[] NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"secret" bytea,
	"last_triggered_at" timestamp,
	"failure_count" integer DEFAULT 0 NOT NULL,
	"created" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "server_alerts" (
	"uuid" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"server_uuid" uuid NOT NULL,
	"kind" "server_alert_kind" NOT NULL,
	"crash_id" bigint,
	"exit_code" integer,
	"oom_killed" boolean DEFAULT false NOT NULL,
	"last_console" varchar(4096),
	"detected_at" timestamp DEFAULT now() NOT NULL,
	"created" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "server_alert_states" (
	"server_uuid" uuid PRIMARY KEY,
	"last_seen_state" varchar(32) NOT NULL,
	"last_seen_at" timestamp DEFAULT now() NOT NULL,
	"last_crash_id" bigint,
	"last_alerted_at" timestamp
);

CREATE INDEX "server_webhooks_server_uuid_idx" ON "server_webhooks" ("server_uuid");
CREATE INDEX "server_alerts_server_uuid_idx" ON "server_alerts" ("server_uuid");
CREATE INDEX "server_alerts_detected_at_idx" ON "server_alerts" ("detected_at");
-- One alert per Wings crash id: the watcher inserts only when no row
-- with this (server, crash) exists, so a retry can never double-alert.
CREATE UNIQUE INDEX "server_alerts_server_crash_idx" ON "server_alerts" ("server_uuid", "crash_id") WHERE "crash_id" IS NOT NULL;
ALTER TABLE "server_webhooks" ADD CONSTRAINT "server_webhooks_server_uuid_servers_uuid_fkey" FOREIGN KEY ("server_uuid") REFERENCES "servers"("uuid") ON DELETE CASCADE;
ALTER TABLE "server_alerts" ADD CONSTRAINT "server_alerts_server_uuid_servers_uuid_fkey" FOREIGN KEY ("server_uuid") REFERENCES "servers"("uuid") ON DELETE CASCADE;
ALTER TABLE "server_alert_states" ADD CONSTRAINT "server_alert_states_server_uuid_servers_uuid_fkey" FOREIGN KEY ("server_uuid") REFERENCES "servers"("uuid") ON DELETE CASCADE;
